// Runs when another workflow fails. Reports only what's needed to investigate:
// no input data, and a capped message in case a provider echoes personal data.
const crypto = require('crypto');
const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');

const { execution, workflow } = $input.first().json;
const failure = {
  executionId: String(execution?.id ?? `unknown-${Date.now()}`),
  workflowName: workflow?.name ?? 'Unknown workflow',
  nodeName: execution?.lastNodeExecuted ?? 'Unknown node',
  message: (execution?.error?.message ?? 'Unknown error').slice(0, 300),
};
console.error('[LendLoop workflow failure]', JSON.stringify(failure));

const body = JSON.stringify(failure);
const timestamp = String(Date.now());
const signature = crypto.createHmac('sha256', secret)
  .update(`${timestamp}.POST./n8n/workflow-failure.${body}`)
  .digest('hex');
return [{ json: { timestamp, signature, body } }];
